import React, { useState } from 'react';
import { 
  Users, 
  ShieldCheck, 
  AlertTriangle, 
  Search, 
  Plus, 
  MessageSquare, 
  User, 
  Key,
  X, 
  TrendingDown, 
  Calendar,
  Pencil,
  ChevronLeft,
  ChevronRight
} from 'lucide-react';

export default function ClientsPage({ 
  onQuickAddClient, 
  onOpenClientCredentials,
  showToast,
  onNavigate 
}) {
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('ALL');
  const [selectedClientIndex, setSelectedClientIndex] = useState(0);
  const [isNoteEditing, setIsNoteEditing] = useState(false);

  const clientData = [
    {
      id: 'c1',
      code: '#MJ-0942',
      name: 'Marcus Johnson',
      email: 'marcus@fitarch.com',
      avatar: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80',
      goal: 'Hypertrophy Phase 2',
      plan: 'Pro Tier - 12 Wk',
      planType: 'pro',
      lastActive: 'Today',
      compliance: 92,
      status: 'ACTIVE',
      joined: 'Active since Jan 2024',
      streak: 14,
      sessions: 48,
      note: 'Marcus is responding well to the volume increase in Phase 2. Slight impingement reported in left shoulder during overhead press. Modified next week\'s programming to substitute with incline DB press and added specific rotator cuff mobility work.',
      lastUpdated: 'Yesterday',
    },
    {
      id: 'c2',
      code: '#SJ-1104',
      name: 'Sarah Jenkins',
      email: 'sarah@fitarch.com',
      avatar: 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=150&q=80',
      goal: 'Endurance Prep',
      plan: 'Basic - 4 Wk',
      planType: 'basic',
      lastActive: '2 days ago',
      compliance: 45,
      status: 'AT RISK',
      joined: 'Active since Feb 2024',
      streak: 3,
      sessions: 18,
      note: 'Compliance dropped this week due to business travel. Needs encouragement for hotel room mobility & bodyweight workouts.',
      lastUpdated: '3 days ago',
    },
    {
      id: 'c3',
      code: '#DT-8832',
      name: 'David Thompson',
      email: 'david@fitarch.com',
      initials: 'DT',
      goal: 'Weight Loss',
      plan: 'Onboarding',
      planType: 'onboarding',
      lastActive: 'Just now',
      compliance: null,
      status: 'ONBOARDING',
      joined: 'Joined Today',
      streak: 1,
      sessions: 2,
      note: 'Initial intake call completed. Target daily calorie deficit set to 500 kcal.',
      lastUpdated: 'Today',
    },
    {
      id: 'c4',
      code: '#ER-2291',
      name: 'Elena Rodriguez',
      email: 'elena@fitarch.com',
      initials: 'ER',
      goal: 'Strength Building',
      plan: 'Pro Tier - 12 Wk',
      planType: 'pro',
      lastActive: 'Yesterday',
      compliance: 88,
      status: 'ACTIVE',
      joined: 'Active since Nov 2023',
      streak: 21,
      sessions: 64,
      note: 'Hit a new deadlift personal record (225 lbs x 5 reps). Excellent recovery metrics.',
      lastUpdated: 'Yesterday',
    },
    {
      id: 'c5',
      code: '#ML-4410',
      name: 'Michael Lee',
      email: 'michael@fitarch.com',
      initials: 'ML',
      goal: 'Marathon Prep',
      plan: 'Basic - 8 Wk',
      planType: 'basic',
      lastActive: '3 days ago',
      compliance: 75,
      status: 'ACTIVE',
      joined: 'Active since Dec 2023',
      streak: 9,
      sessions: 32,
      note: 'Long weekend run (18 miles) logged successfully. Hydration & carb loading protocol followed.',
      lastUpdated: '4 days ago',
    },
  ];

  // Filtering
  const filteredClients = clientData.filter((c) => {
    const matchesSearch = c.name.toLowerCase().includes(searchQuery.toLowerCase()) || c.code.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesStatus = statusFilter === 'ALL' || c.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  const selectedClient = clientData[selectedClientIndex] || clientData[0];
  const [noteText, setNoteText] = useState(selectedClient.note);

  const handleSaveNote = () => {
    selectedClient.note = noteText;
    setIsNoteEditing(false);
    if (showToast) showToast('Updated trainer note');
  };

  return (
    <div className="space-y-6">
      {/* Header Controls Bar */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h1 className="font-serif-header text-3xl font-bold text-white tracking-tight">
          Clients Directory
        </h1>

        <div className="flex flex-wrap items-center gap-3">
          {/* Search Bar */}
          <div className="relative w-56">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-400" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search clients..."
              className="w-full bg-[#131926] text-slate-200 text-xs rounded-xl pl-9 pr-3 py-2 border border-slate-700/60 focus:outline-none focus:border-blue-500"
            />
          </div>

          {/* Status Filter */}
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="bg-[#131926] text-slate-300 text-xs font-semibold rounded-xl px-3 py-2 border border-slate-700/60 focus:outline-none focus:border-blue-500 cursor-pointer"
          >
            <option value="ALL">Status: All</option>
            <option value="ACTIVE">Active</option>
            <option value="AT RISK">At Risk</option>
            <option value="ONBOARDING">Onboarding</option>
            <option value="FROZEN">Frozen / Suspended</option>
          </select>

          {/* Add New Client Button */}
          <button
            onClick={onQuickAddClient}
            className="flex items-center gap-2 py-2 px-4 bg-gradient-to-r from-blue-300 via-sky-200 to-blue-200 hover:from-blue-200 hover:to-sky-100 text-slate-950 font-bold text-xs rounded-xl shadow-md transition-all cursor-pointer"
          >
            <Plus className="w-4 h-4" />
            <span>Add New Client</span>
          </button>
        </div>
      </div>

      {/* KPI Cards Row */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        {/* Total Clients */}
        <div className="bg-[#121724] border border-slate-800 rounded-2xl p-5 shadow-lg flex items-center justify-between">
          <div>
            <span className="text-[11px] font-bold tracking-wider text-slate-400 uppercase">
              TOTAL CLIENTS
            </span>
            <div className="text-3xl font-extrabold text-white mt-1">42</div>
          </div>
          <div className="w-10 h-10 rounded-full bg-slate-800/80 border border-slate-700/60 flex items-center justify-center text-blue-400">
            <Users className="w-5 h-5" />
          </div>
        </div>

        {/* Active Subscriptions */}
        <div className="bg-[#121724] border border-slate-800 rounded-2xl p-5 shadow-lg flex items-center justify-between">
          <div>
            <span className="text-[11px] font-bold tracking-wider text-slate-400 uppercase">
              ACTIVE SUBSCRIPTIONS
            </span>
            <div className="text-3xl font-extrabold text-white mt-1">35</div>
          </div>
          <div className="w-10 h-10 rounded-full bg-slate-800/80 border border-slate-700/60 flex items-center justify-center text-blue-400">
            <ShieldCheck className="w-5 h-5" />
          </div>
        </div>

        {/* At Risk */}
        <div className="bg-[#121724] border border-slate-800 rounded-2xl p-5 shadow-lg flex items-center justify-between">
          <div>
            <span className="text-[11px] font-bold tracking-wider text-slate-400 uppercase">
              AT RISK
            </span>
            <div className="text-3xl font-extrabold text-red-400 mt-1">3</div>
          </div>
          <div className="w-10 h-10 rounded-full bg-red-950/40 border border-red-900/60 flex items-center justify-center text-red-400">
            <AlertTriangle className="w-5 h-5" />
          </div>
        </div>
      </div>

      {/* Main 2-Column Section */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        {/* Table Matrix (Col 8) */}
        <div className="lg:col-span-8 bg-[#121724] border border-slate-800/90 rounded-2xl p-6 shadow-xl space-y-4">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse min-w-[700px]">
              <thead>
                <tr className="border-b border-slate-800 text-[11px] font-semibold text-slate-400 tracking-wider">
                  <th className="py-3 px-3">CLIENT</th>
                  <th className="py-3 px-3">GOAL</th>
                  <th className="py-3 px-3">CURRENT PLAN</th>
                  <th className="py-3 px-3">LAST ACTIVE</th>
                  <th className="py-3 px-3">COMPLIANCE</th>
                  <th className="py-3 px-3 text-center">STATUS</th>
                  <th className="py-3 px-3 text-right">ACTIONS</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/60 text-xs">
                {filteredClients.map((client, idx) => {
                  const isSelected = selectedClient.id === client.id;

                  return (
                    <tr
                      key={client.id}
                      onClick={() => {
                        setSelectedClientIndex(idx);
                        setNoteText(client.note);
                      }}
                      className={`cursor-pointer transition-all ${
                        isSelected
                          ? 'bg-[#182133] border-l-4 border-l-blue-400'
                          : 'hover:bg-slate-800/40'
                      }`}
                    >
                      {/* Client info */}
                      <td className="py-3.5 px-3">
                        <div className="flex items-center gap-3">
                          {client.avatar ? (
                            <img
